    // Wait for network activities to finish
    await page.waitForTimeout(5000);

    await page.locator("body").click({ position: {"x": 600, "y": 400} });
    await page.evaluate(() => { const el = document.querySelector('[data-type="wysiwyg"]'); return el ? `found: data-type=${el.dataset.type}, classes=${el.className}` : 'not found'; });
    await expect(page.locator('[data-type="wysiwyg"]')).toBeVisible();
